export const SCHEMA_SQL="\n-- SecretNests Cloudflare D1 schema\nPRAGMA foreign_keys = ON;\n\nCREATE TABLE IF NOT EXISTS hotels (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  slug TEXT NOT NULL UNIQUE,\n  google_place_id TEXT,\n  description TEXT,\n  country TEXT,\n  city TEXT,\n  region TEXT,\n  lat REAL,\n  lng REAL,\n  address TEXT,\n  formatted_address TEXT,\n  website TEXT,\n  phone TEXT,\n  google_rating REAL,\n  google_review_count INTEGER,\n  google_price_level INTEGER,\n  hotel_category TEXT,\n  reddit_mention_count INTEGER NOT NULL DEFAULT 0,\n  is_published INTEGER NOT NULL DEFAULT 0,\n  published_at TEXT,\n  booking_url TEXT,\n  highlights_json TEXT,\n  best_for_json TEXT,\n  not_ideal_for_json TEXT,\n  price_estimate_min INTEGER,\n  price_estimate_max INTEGER,\n  created_at TEXT,\n  updated_at TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_hotels_slug ON hotels(slug);\nCREATE INDEX IF NOT EXISTS idx_hotels_city ON hotels(city);\nCREATE INDEX IF NOT EXISTS idx_hotels_country ON hotels(country);\nCREATE INDEX IF NOT EXISTS idx_hotels_published ON hotels(is_published);\n\nCREATE TABLE IF NOT EXISTS creator_profiles (\n  id TEXT PRIMARY KEY,\n  user_id TEXT UNIQUE,\n  handle TEXT NOT NULL UNIQUE,\n  display_name TEXT NOT NULL,\n  bio TEXT,\n  avatar_url TEXT,\n  taste_profile_json TEXT NOT NULL DEFAULT '[]',\n  is_public INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS stays (\n  id TEXT PRIMARY KEY,\n  creator_id TEXT NOT NULL REFERENCES creator_profiles(id) ON DELETE CASCADE,\n  hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  stay_month TEXT,\n  nights INTEGER,\n  party_type TEXT,\n  room_type TEXT,\n  booking_channel TEXT,\n  paid_nightly_rate REAL,\n  total_paid REAL,\n  currency TEXT NOT NULL DEFAULT 'USD',\n  verified INTEGER NOT NULL DEFAULT 0,\n  verification_method TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX IF NOT EXISTS idx_stays_creator ON stays(creator_id);\nCREATE INDEX IF NOT EXISTS idx_stays_hotel ON stays(hotel_id);\n\nCREATE TABLE IF NOT EXISTS trip_reports (\n  id TEXT PRIMARY KEY,\n  stay_id TEXT NOT NULL UNIQUE REFERENCES stays(id) ON DELETE CASCADE,\n  creator_id TEXT NOT NULL REFERENCES creator_profiles(id) ON DELETE CASCADE,\n  hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  title TEXT,\n  review_text TEXT,\n  verdict TEXT,\n  would_return INTEGER,\n  standout_json TEXT NOT NULL DEFAULT '[]',\n  disappointments_json TEXT NOT NULL DEFAULT '[]',\n  status TEXT NOT NULL DEFAULT 'draft',\n  published_at TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS value_opinions (\n  id TEXT PRIMARY KEY,\n  stay_id TEXT NOT NULL REFERENCES stays(id) ON DELETE CASCADE,\n  creator_id TEXT NOT NULL REFERENCES creator_profiles(id) ON DELETE CASCADE,\n  hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  paid_nightly_rate REAL,\n  would_pay_again REAL,\n  worth_it_below REAL,\n  hard_to_justify_above REAL,\n  currency TEXT NOT NULL DEFAULT 'USD',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX IF NOT EXISTS idx_value_hotel ON value_opinions(hotel_id);\n\nCREATE TABLE IF NOT EXISTS hotel_value_snapshots (\n  id TEXT PRIMARY KEY,\n  hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  traveler_low REAL,\n  traveler_high REAL,\n  median_would_pay REAL,\n  sample_size INTEGER NOT NULL DEFAULT 0,\n  current_price REAL,\n  value_classification TEXT,\n  currency TEXT NOT NULL DEFAULT 'USD',\n  calculated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS lists (\n  id TEXT PRIMARY KEY,\n  creator_id TEXT NOT NULL REFERENCES creator_profiles(id) ON DELETE CASCADE,\n  slug TEXT NOT NULL,\n  title TEXT NOT NULL,\n  description TEXT,\n  is_public INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(creator_id, slug)\n);\n\nCREATE TABLE IF NOT EXISTS list_items (\n  id TEXT PRIMARY KEY,\n  list_id TEXT NOT NULL REFERENCES lists(id) ON DELETE CASCADE,\n  hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  note TEXT,\n  rank INTEGER,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(list_id, hotel_id)\n);\n\nCREATE TABLE IF NOT EXISTS affiliate_clicks (\n  id TEXT PRIMARY KEY,\n  hotel_id TEXT REFERENCES hotels(id) ON DELETE SET NULL,\n  creator_id TEXT REFERENCES creator_profiles(id) ON DELETE SET NULL,\n  list_id TEXT REFERENCES lists(id) ON DELETE SET NULL,\n  provider TEXT NOT NULL,\n  destination_url TEXT NOT NULL,\n  partner_sub_id TEXT,\n  session_id TEXT,\n  referrer TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS booking_conversions (\n  id TEXT PRIMARY KEY,\n  click_id TEXT REFERENCES affiliate_clicks(id) ON DELETE SET NULL,\n  provider TEXT NOT NULL,\n  partner_booking_id TEXT,\n  hotel_id TEXT REFERENCES hotels(id) ON DELETE SET NULL,\n  creator_id TEXT REFERENCES creator_profiles(id) ON DELETE SET NULL,\n  booking_value REAL,\n  commission_value REAL,\n  currency TEXT NOT NULL DEFAULT 'USD',\n  status TEXT,\n  booked_at TEXT,\n  stay_at TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS creator_earnings (\n  id TEXT PRIMARY KEY,\n  creator_id TEXT NOT NULL REFERENCES creator_profiles(id) ON DELETE CASCADE,\n  booking_conversion_id TEXT REFERENCES booking_conversions(id) ON DELETE SET NULL,\n  amount REAL NOT NULL,\n  currency TEXT NOT NULL DEFAULT 'USD',\n  status TEXT NOT NULL DEFAULT 'pending',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  paid_at TEXT\n);\n\nCREATE TABLE IF NOT EXISTS media_assets (\n  id TEXT PRIMARY KEY,\n  hotel_id TEXT REFERENCES hotels(id) ON DELETE CASCADE,\n  creator_id TEXT REFERENCES creator_profiles(id) ON DELETE SET NULL,\n  source_type TEXT NOT NULL,\n  source_url TEXT,\n  source_provider TEXT,\n  photographer TEXT,\n  license_code TEXT,\n  license_url TEXT,\n  attribution_text TEXT,\n  rights_status TEXT NOT NULL DEFAULT 'needs_review',\n  permission_reference TEXT,\n  original_url TEXT,\n  r2_key TEXT,\n  width INTEGER,\n  height INTEGER,\n  mime_type TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX IF NOT EXISTS idx_media_hotel ON media_assets(hotel_id);\nCREATE INDEX IF NOT EXISTS idx_media_rights ON media_assets(rights_status);\n\nCREATE TABLE IF NOT EXISTS reddit_evidence (\n  id TEXT PRIMARY KEY,\n  post_id TEXT NOT NULL,\n  hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  hotel_name_raw TEXT NOT NULL,\n  sentiment TEXT,\n  attributes_json TEXT,\n  best_for_json TEXT,\n  avoid_if_json TEXT,\n  tradeoffs_json TEXT,\n  regret_signal INTEGER NOT NULL DEFAULT 0,\n  price_mentioned REAL,\n  trip_context TEXT,\n  confidence TEXT,\n  source_url TEXT,\n  created_at TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_reddit_evidence_hotel ON reddit_evidence(hotel_id);\n\n-- SecretNests product/analytics expansion\nPRAGMA foreign_keys = ON;\n\nCREATE TABLE IF NOT EXISTS analytics_events (\n  id TEXT PRIMARY KEY,\n  event_name TEXT NOT NULL,\n  hotel_id TEXT REFERENCES hotels(id) ON DELETE SET NULL,\n  creator_id TEXT REFERENCES creator_profiles(id) ON DELETE SET NULL,\n  list_id TEXT REFERENCES lists(id) ON DELETE SET NULL,\n  path TEXT,\n  session_id TEXT,\n  referrer TEXT,\n  user_agent TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE INDEX IF NOT EXISTS idx_analytics_event_name_created ON analytics_events(event_name, created_at);\nCREATE INDEX IF NOT EXISTS idx_analytics_hotel_created ON analytics_events(hotel_id, created_at);\n\nCREATE TABLE IF NOT EXISTS auth_identities (\n  id TEXT PRIMARY KEY,\n  provider TEXT NOT NULL,\n  provider_subject TEXT NOT NULL,\n  email TEXT,\n  email_verified INTEGER NOT NULL DEFAULT 0,\n  creator_id TEXT REFERENCES creator_profiles(id) ON DELETE SET NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(provider, provider_subject)\n);\n\nCREATE INDEX IF NOT EXISTS idx_auth_email ON auth_identities(email);\n\nCREATE TABLE IF NOT EXISTS sessions (\n  id TEXT PRIMARY KEY,\n  auth_identity_id TEXT NOT NULL REFERENCES auth_identities(id) ON DELETE CASCADE,\n  token_hash TEXT NOT NULL UNIQUE,\n  expires_at TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  last_seen_at TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_sessions_expires ON sessions(expires_at);\n\nCREATE TABLE IF NOT EXISTS stay_verification_artifacts (\n  id TEXT PRIMARY KEY,\n  stay_id TEXT NOT NULL REFERENCES stays(id) ON DELETE CASCADE,\n  r2_key TEXT,\n  source_type TEXT NOT NULL,\n  status TEXT NOT NULL DEFAULT 'pending',\n  redaction_status TEXT NOT NULL DEFAULT 'pending',\n  reviewer_note TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  reviewed_at TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_stay_verification_stay ON stay_verification_artifacts(stay_id);\n\n-- SecretNests launch-readiness additions\nPRAGMA foreign_keys = ON;\n\nCREATE TABLE IF NOT EXISTS trip_submissions (\n  id TEXT PRIMARY KEY,\n  contact_email TEXT,\n  hotel_name TEXT NOT NULL,\n  city TEXT,\n  stay_month TEXT,\n  paid_nightly_rate REAL,\n  would_pay_again REAL,\n  room_type TEXT,\n  booking_channel TEXT,\n  notes TEXT,\n  status TEXT NOT NULL DEFAULT 'pending',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  reviewed_at TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_trip_submissions_status_created\n  ON trip_submissions(status, created_at);\n\nCREATE INDEX IF NOT EXISTS idx_trip_submissions_hotel\n  ON trip_submissions(hotel_name);\n\n-- SecretNests product expansion: valuation, aliases, affiliates, moderation, media rights, abuse controls\nPRAGMA foreign_keys = ON;\n\nALTER TABLE creator_profiles ADD COLUMN is_demo INTEGER NOT NULL DEFAULT 0;\n\nALTER TABLE hotel_value_snapshots ADD COLUMN confidence TEXT;\nALTER TABLE hotel_value_snapshots ADD COLUMN p25_would_pay REAL;\nALTER TABLE hotel_value_snapshots ADD COLUMN p75_would_pay REAL;\nALTER TABLE hotel_value_snapshots ADD COLUMN methodology_version TEXT;\n\nCREATE TABLE IF NOT EXISTS hotel_slug_aliases (\n  alias_slug TEXT PRIMARY KEY,\n  hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_hotel_slug_alias_hotel ON hotel_slug_aliases(hotel_id);\n\nCREATE TABLE IF NOT EXISTS affiliate_providers (\n  id TEXT PRIMARY KEY,\n  name TEXT NOT NULL,\n  provider_type TEXT NOT NULL,\n  enabled INTEGER NOT NULL DEFAULT 1,\n  config_json TEXT NOT NULL DEFAULT '{}',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS hotel_booking_links (\n  id TEXT PRIMARY KEY,\n  hotel_id TEXT NOT NULL REFERENCES hotels(id) ON DELETE CASCADE,\n  provider_id TEXT NOT NULL REFERENCES affiliate_providers(id) ON DELETE CASCADE,\n  destination_url TEXT NOT NULL,\n  priority INTEGER NOT NULL DEFAULT 100,\n  enabled INTEGER NOT NULL DEFAULT 1,\n  metadata_json TEXT NOT NULL DEFAULT '{}',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  UNIQUE(hotel_id, provider_id, destination_url)\n);\nCREATE INDEX IF NOT EXISTS idx_booking_links_hotel ON hotel_booking_links(hotel_id, enabled, priority);\n\nCREATE TABLE IF NOT EXISTS submission_moderation (\n  id TEXT PRIMARY KEY,\n  submission_id TEXT NOT NULL REFERENCES trip_submissions(id) ON DELETE CASCADE,\n  action TEXT NOT NULL,\n  hotel_id TEXT REFERENCES hotels(id) ON DELETE SET NULL,\n  moderator_email TEXT,\n  note TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_submission_moderation_submission ON submission_moderation(submission_id, created_at);\n\nCREATE TABLE IF NOT EXISTS media_rights_reviews (\n  id TEXT PRIMARY KEY,\n  media_asset_id TEXT NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE,\n  previous_status TEXT,\n  new_status TEXT NOT NULL,\n  reviewer_email TEXT,\n  note TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_media_rights_review_asset ON media_rights_reviews(media_asset_id, created_at);\n\nCREATE TABLE IF NOT EXISTS media_ingest_requests (\n  id TEXT PRIMARY KEY,\n  hotel_id TEXT REFERENCES hotels(id) ON DELETE CASCADE,\n  creator_id TEXT REFERENCES creator_profiles(id) ON DELETE SET NULL,\n  source_type TEXT NOT NULL,\n  source_url TEXT,\n  source_provider TEXT,\n  proposed_rights_status TEXT NOT NULL DEFAULT 'needs_review',\n  permission_reference TEXT,\n  attribution_text TEXT,\n  status TEXT NOT NULL DEFAULT 'pending',\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  reviewed_at TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_media_ingest_status ON media_ingest_requests(status, created_at);\n\nCREATE TABLE IF NOT EXISTS request_rate_limits (\n  bucket_key TEXT PRIMARY KEY,\n  window_start TEXT NOT NULL,\n  count INTEGER NOT NULL DEFAULT 0,\n  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS zero_result_searches (\n  id TEXT PRIMARY KEY,\n  query TEXT NOT NULL,\n  session_id TEXT,\n  path TEXT,\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\nCREATE INDEX IF NOT EXISTS idx_zero_search_created ON zero_result_searches(created_at);\n\n\nINSERT OR IGNORE INTO affiliate_providers (id,name,provider_type,enabled,config_json)\nVALUES\n  ('direct','Direct hotel','direct',1,'{}'),\n  ('travelpayouts','Travelpayouts','affiliate',0,'{}'),\n  ('advisor','Travel advisor referral','referral',0,'{}');\n";
